func:
// DETECTAR FALLA DE LA BOMBA EQ01
// Llega un mensaje MQTT por variable (CAUDAL, PRESION, CORRIENTE, VIBRACION, ESTADO).
// Guardamos el último valor de cada una y vemos si alguna pasó el límite crítico.
// Solo avisamos cuando la bomba PASA de normal a falla (no en cada muestra).

// Límites críticos del catálogo de variables de AquaMonitor
const LIMITE = {
    VIBRACION_MAX: 7.1,   // mm/s
    CAUDAL_MIN: 70,       // m3/h
    CAUDAL_MAX: 175,      // m3/h
    PRESION_MIN: 2.5,     // bar
    PRESION_MAX: 6.5,     // bar
    CORRIENTE_MAX: 65     // A
};
// Segundos seguidos en normal antes de dar la falla por terminada
const REARME_S = Number(env.get('ALERTA_REARME_S') || 60);

const p = msg.payload;
if (!p || typeof p !== 'object' || p.value === undefined || p.value === null) { return null; }

const variable = String(msg.topic || '').split('/').pop().toUpperCase();
const valor = Number(p.value);
if (!variable || Number.isNaN(valor)) { return null; }

const ahora = Date.now();
const est = flow.get('bomba') || { valores: {}, enFalla: false, desde: null, okDesde: null };
est.valores[variable] = valor;
const v = est.valores;

// ¿Qué variables están hoy en estado crítico?
const motivos = [];
if (v.ESTADO === 0) {
    motivos.push({ variable: 'ESTADO', valor: 0, texto: 'la bomba está parada (parada imprevista)' });
}
if (v.VIBRACION > LIMITE.VIBRACION_MAX) {
    motivos.push({ variable: 'VIBRACION', valor: v.VIBRACION, texto: 'vibración ' + v.VIBRACION + ' mm/s (límite crítico ' + LIMITE.VIBRACION_MAX + ')' });
}
if (v.CAUDAL < LIMITE.CAUDAL_MIN || v.CAUDAL > LIMITE.CAUDAL_MAX) {
    motivos.push({ variable: 'CAUDAL', valor: v.CAUDAL, texto: 'caudal ' + v.CAUDAL + ' m3/h fuera de ' + LIMITE.CAUDAL_MIN + '-' + LIMITE.CAUDAL_MAX });
}
if (v.PRESION < LIMITE.PRESION_MIN || v.PRESION > LIMITE.PRESION_MAX) {
    motivos.push({ variable: 'PRESION', valor: v.PRESION, texto: 'presión ' + v.PRESION + ' bar fuera de ' + LIMITE.PRESION_MIN + '-' + LIMITE.PRESION_MAX });
}
if (v.CORRIENTE > LIMITE.CORRIENTE_MAX) {
    motivos.push({ variable: 'CORRIENTE', valor: v.CORRIENTE, texto: 'corriente ' + v.CORRIENTE + ' A (límite crítico ' + LIMITE.CORRIENTE_MAX + ')' });
}

let evento = null;
if (motivos.length > 0) {
    est.okDesde = null;
    if (!est.enFalla) {                       // pasó de normal a falla: AVISAR
        est.enFalla = true;
        est.desde = ahora;
        evento = { tipo: 'falla', ts: ahora, motivos: motivos, valores: Object.assign({}, v) };
    }
} else if (est.enFalla) {                     // está normal, pero venía en falla
    if (est.okDesde === null) { est.okDesde = ahora; }
    if (ahora - est.okDesde >= REARME_S * 1000) {   // normal sostenido: cerrar la falla
        est.enFalla = false;
        evento = { tipo: 'recuperada', ts: ahora, duracionS: Math.round((ahora - est.desde) / 1000), valores: Object.assign({}, v) };
    }
}

flow.set('bomba', est);
node.status(est.enFalla
    ? { fill: 'red', shape: 'dot', text: 'EN FALLA' }
    : { fill: 'green', shape: 'dot', text: 'normal' });

if (!evento) { return null; }
msg.evento = evento;
return msg;

// ARMAR LOS AVISOS: un mismo evento sale por 3 caminos
//   salida 1 -> mail (nodo e-mail)
//   salida 2 -> Telegram (nodo http request, API de bots de Telegram)
//   salida 3 -> historial en QuestDB (tabla eventos_bomba, para Grafana)
// Los datos sensibles NO están en el flow: se leen de variables de entorno.

const e = msg.evento;
if (!e) { return null; }

const hora = new Date(e.ts || Date.now()).toLocaleString('es-AR', {
    timeZone: 'America/Argentina/Buenos_Aires', hourCycle: 'h23',
    day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit'
});
const quien = 'Bomba de ingreso EQ01 (planta PTEF, área CAPT)';
const v = e.valores || {};
const lectura = ['CAUDAL', 'PRESION', 'CORRIENTE', 'VIBRACION']
    .filter(k => v[k] !== undefined)
    .map(k => k + ' ' + v[k])
    .join(' | ');

let asunto, texto, motivo, valorEvento, detalle;
if (e.tipo === 'falla') {
    const lista = (e.motivos || []).map(m => '- ' + m.texto).join('\n');
    asunto = 'FALLA: ' + quien;
    texto = 'FALLA DE BOMBA\n' + quien + '\nHora: ' + hora + '\nMotivo:\n' + lista + (lectura ? '\nÚltimos valores: ' + lectura : '');
    motivo = (e.motivos && e.motivos[0] && e.motivos[0].variable) || 'DESCONOCIDO';
    valorEvento = (e.motivos && e.motivos[0] && Number(e.motivos[0].valor)) || 0;
    detalle = (e.motivos || []).map(m => m.texto).join('; ');
} else {
    asunto = 'Normalizada: ' + quien;
    texto = 'BOMBA NORMALIZADA\n' + quien + '\nHora: ' + hora + '\nEstuvo en falla ' + e.duracionS + ' segundos.';
    motivo = 'NORMALIZADA';
    valorEvento = Number(e.duracionS) || 0;
    detalle = 'estuvo en falla ' + e.duracionS + ' s';
}
if (e.prueba) { texto = '[PRUEBA] ' + texto; asunto = '[PRUEBA] ' + asunto; }

// ---- salida 1: mail
const to = env.get('ALERT_MAIL_TO');
let salidaMail = null;
if (to) { salidaMail = { to: to, topic: asunto, payload: texto }; }
else { node.warn('Falta ALERT_MAIL_TO: no se envía el mail'); }

// ---- salida 2: Telegram
const token = env.get('TELEGRAM_BOT_TOKEN');
const chat = env.get('TELEGRAM_CHAT_ID');
const base = env.get('TELEGRAM_API_BASE') || 'https://api.telegram.org';
let salidaTelegram = null;
if (token && chat) {
    salidaTelegram = {
        method: 'POST',
        url: base + '/bot' + token + '/sendMessage',
        headers: { 'content-type': 'application/json' },
        payload: { chat_id: chat, text: texto }
    };
} else { node.warn('Faltan TELEGRAM_BOT_TOKEN o TELEGRAM_CHAT_ID: no se envía el mensaje'); }

// ---- salida 3: historial en QuestDB (formato ILP, una línea por evento)
const qdb = env.get('QUESTDB_HTTP_URL');
let salidaQdb = null;
if (qdb && !e.prueba) {
    const limpio = String(detalle).replace(/[\r\n]+/g, ' ').replace(/\\/g, '/').replace(/"/g, "'");
    const linea = 'eventos_bomba,equipo=EQ01,tipo=' + (e.tipo === 'falla' ? 'falla' : 'recuperada') +
        ',motivo=' + String(motivo).replace(/[^A-Za-z0-9_]/g, '_') +
        ' valor=' + valorEvento + ',detalle="' + limpio + '" ' + String(e.ts || Date.now()) + '000000\n';
    const headers = { 'content-type': 'text/plain' };
    const tokenQ = env.get('QUESTDB_TOKEN');
    if (tokenQ) { headers.authorization = 'Bearer ' + tokenQ; }
    salidaQdb = { method: 'POST', url: qdb + '/write?precision=n', headers: headers, payload: linea };
}

return [salidaMail, salidaTelegram, salidaQdb];
